class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

arguments.new_str:
class SyncJob
{
    // Breaking change 5: Raw SQL queries must use the new property names.
    // "Discriminator" is preserved via HasJsonPropertyName above, so raw SQL still works.
    // If you had used "$type" in queries, you'd need to revert to "Discriminator".
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        // Use async save — EF Core 9 Cosmos provider prefers async I/O
        await context.SaveChangesAsync();
    }
}

