using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
using System;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed the discriminator JSON property
            // from "Discriminator" to "$type". Existing documents use "Discriminator",
            // so we explicitly name the discriminator property to preserve the old mapping.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 no longer includes the discriminator in the
            // JSON "id" property by default. Existing documents use "Blog|1" format.
            // Re-enable the old behavior.
            entity.HasDiscriminatorInJsonId();

            // Breaking change 3: HasIndex() now throws at runtime for Cosmos provider
            // in EF Core 9. The previous HasIndex(b => b.Name) has been removed.
            // Use Cosmos indexing policy directly in Azure portal or ARM templates.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "BlogDb");
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; }

